/// `M_HidJoystick::Service`: receives [`ServiceMessage`], sends [`ClientMessage`].
pub type Service = crate::Endpoint<ServiceRole>;

/// Typed senders, one per outgoing operation. They encode straight from borrowed data.
impl crate::Endpoint<ServiceRole> {
    /// Triggered every time a Joystick button is selected or unselected.
    pub fn event_button(&self, button_index: u32, button_name: &str, is_selected: bool) -> crate::Result<()> {
        let mut w = Writer::default();
        button_index.encode(&mut w);
        button_name.encode(&mut w);
        is_selected.encode(&mut w);
        self.send_raw(0, w.as_bytes())
    }

    /// Triggered every time a increment encoder is activated.
    pub fn event_increment(&self, index: u32, steps: i32) -> crate::Result<()> {
        let mut w = Writer::default();
        index.encode(&mut w);
        steps.encode(&mut w);
        self.send_raw(1, w.as_bytes())
    }

    /// Contains the static settings for a Joystick.
    /// This should be provided at startup and in the event of degraded functionality,
    /// e.g. due to an internal failure.
    pub fn report_joystick_settings(&self, settings: &JoystickSettingsType) -> crate::Result<()> {
        let mut w = Writer::default();
        settings.encode(&mut w);
        self.send_raw(2, w.as_bytes())
    }

    /// Reports the current axis position every time a joystick axis is moved.
    pub fn report_axis(&self, key_axis_index: u32, value: f64, is_removed: bool) -> crate::Result<()> {
        let mut w = Writer::default();
        key_axis_index.encode(&mut w);
        value.encode(&mut w);
        is_removed.encode(&mut w);
        self.send_raw(3, w.as_bytes())
    }

    /// Reports the specified input value.
    pub fn report_input_value(&self, key_value_input_index: u32, value: &crate::common::PropertyType, is_removed: bool) -> crate::Result<()> {
        let mut w = Writer::default();
        key_value_input_index.encode(&mut w);
        value.encode(&mut w);
        is_removed.encode(&mut w);
        self.send_raw(4, w.as_bytes())
    }

    /// Reports the specified menu's status.
    pub fn report_menu_status(&self, key_menu_index: u32, is_active: bool, is_removed: bool) -> crate::Result<()> {
        let mut w = Writer::default();
        key_menu_index.encode(&mut w);
        is_active.encode(&mut w);
        is_removed.encode(&mut w);
        self.send_raw(5, w.as_bytes())
    }

    /// Contains the joystick input curve.
    pub fn report_joystick_curve(&self, key_axis_index: u32, curve: &str, is_removed: bool) -> crate::Result<()> {
        let mut w = Writer::default();
        key_axis_index.encode(&mut w);
        curve.encode(&mut w);
        is_removed.encode(&mut w);
        self.send_raw(6, w.as_bytes())
    }

}

/// Marker type for the client side of `M_HidJoystick`.
#[derive(Debug, Clone, Copy)]
pub enum ClientRole {}

impl crate::Role for ClientRole {
    type Incoming = ClientMessage;
    type Outgoing = ServiceMessage;
    const NAME: &'static str = "M_HidJoystick::Client";

    fn vtable() -> &'static onboardapi_sys::obapi_vtable {
        // SAFETY: the vtable is an immutable static defined by the C++ shim.
        unsafe { &*(&raw const onboardapi_sys::obapi_HidJoystick_client_vtable) }
    }
}

impl crate::ClientSide for ClientRole {}

/// `M_HidJoystick::Client`: receives [`ClientMessage`], sends [`ServiceMessage`].
pub type Client = crate::Endpoint<ClientRole>;

/// Typed senders, one per outgoing operation. They encode straight from borrowed data.
impl crate::Endpoint<ClientRole> {
    /// Command to check if service is alive.
    /// If the service is not available, then an exception will be thrown.
    pub fn cmd_is_joystick_alive(&self) -> crate::Result<()> {
        let w = Writer::default();
        self.send_raw(0, w.as_bytes())
    }

    /// Parametrises joystick input scaling, i.e. how quickly a mount follows
    /// a joystick input (linearly, quadratically, ...).
    pub fn config_joystick_curve(&self, key_axis_index: u32, curve: &str, is_removed: bool) -> crate::Result<()> {
        let mut w = Writer::default();
        key_axis_index.encode(&mut w);
        curve.encode(&mut w);
        is_removed.encode(&mut w);
        self.send_raw(1, w.as_bytes())
    }

}

